-- Initial schema for the MVP (docs/SPEC-MVP.md, "Modelo de dados").
-- Ids are UUID v7, generated by the application; uuidv7() is only a fallback.
-- Closed value sets are text columns with CHECK constraints, which are easier
-- to evolve in later migrations than PostgreSQL enum types.

CREATE TABLE document (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    filename     text        NOT NULL,
    mime         text        NOT NULL CHECK (mime IN ('application/pdf', 'image/jpeg', 'image/png')),
    size_bytes   bigint      NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 20971520),
    sha256       text        NOT NULL UNIQUE CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    storage_path text        NOT NULL,
    uploaded_at  timestamptz NOT NULL
);

CREATE TABLE source (
    id                  uuid PRIMARY KEY DEFAULT uuidv7(),
    kind                text        NOT NULL CHECK (kind IN ('telegram_text', 'telegram_command', 'reminder_reply', 'web', 'document')),
    raw_text            text,
    telegram_message_id bigint,
    document_id         uuid REFERENCES document (id),
    received_at         timestamptz NOT NULL
);

CREATE TABLE extraction_run (
    id             uuid PRIMARY KEY DEFAULT uuidv7(),
    model          text        NOT NULL,
    prompt_version text        NOT NULL,
    input_hash     text        NOT NULL,
    output_json    jsonb,
    created_at     timestamptz NOT NULL
);

CREATE TABLE analyte (
    code           text PRIMARY KEY,
    display_name   text   NOT NULL,
    canonical_unit text,
    body_region    text CHECK (body_region IN ('head', 'neck', 'chest', 'abdomen', 'upper_back', 'lower_back',
                                               'left_arm', 'right_arm', 'left_knee', 'right_knee',
                                               'left_leg', 'right_leg', 'systemic')),
    aliases        text[] NOT NULL DEFAULT '{}'
);

CREATE TABLE event (
    id                uuid PRIMARY KEY DEFAULT uuidv7(),
    type              text        NOT NULL CHECK (type IN ('symptom', 'sleep', 'water', 'exercise', 'weight', 'meal', 'medication', 'note')),
    concept           text,
    body_region       text CHECK (body_region IN ('head', 'neck', 'chest', 'abdomen', 'upper_back', 'lower_back',
                                                  'left_arm', 'right_arm', 'left_knee', 'right_knee',
                                                  'left_leg', 'right_leg', 'systemic')),
    value_num         numeric,
    value_text        text,
    unit              text,
    intensity         smallint CHECK (intensity BETWEEN 0 AND 10),
    occurred_start    timestamptz NOT NULL,
    occurred_end      timestamptz,
    time_precision    text        NOT NULL CHECK (time_precision IN ('exact', 'day', 'month', 'approx')),
    recorded_at       timestamptz NOT NULL,
    status            text        NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'confirmed', 'discarded')),
    source_id         uuid        NOT NULL REFERENCES source (id),
    source_locator    text,
    created_via       text        NOT NULL CHECK (created_via IN ('command', 'free_text', 'reminder_reply', 'web')),
    extraction_run_id uuid REFERENCES extraction_run (id),
    dedupe_key        text        NOT NULL UNIQUE,
    CHECK (occurred_end IS NULL OR occurred_end >= occurred_start)
);

CREATE TABLE exam (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    collected_on date        NOT NULL,
    lab_name     text,
    document_id  uuid REFERENCES document (id),
    source_id    uuid        NOT NULL REFERENCES source (id),
    created_at   timestamptz NOT NULL
);

CREATE TABLE lab_result (
    id               uuid PRIMARY KEY DEFAULT uuidv7(),
    exam_id          uuid NOT NULL REFERENCES exam (id) ON DELETE CASCADE,
    analyte_code     text REFERENCES analyte (code),
    analyte_name_raw text NOT NULL,
    value_num        numeric,
    value_text       text,
    unit             text,
    ref_low          numeric,
    ref_high         numeric,
    ref_text         text,
    status           text NOT NULL CHECK (status IN ('below', 'normal', 'above', 'no_reference')),
    source_locator   text,
    CHECK (value_num IS NOT NULL OR value_text IS NOT NULL),
    CHECK (ref_low IS NULL OR ref_high IS NULL OR ref_low <= ref_high)
);

CREATE TABLE appointment (
    id                uuid PRIMARY KEY DEFAULT uuidv7(),
    occurred_on       date NOT NULL,
    specialty         text,
    professional_name text,
    notes             text,
    source_id         uuid NOT NULL REFERENCES source (id)
);

CREATE TABLE guidance (
    id             uuid PRIMARY KEY DEFAULT uuidv7(),
    appointment_id uuid NOT NULL REFERENCES appointment (id) ON DELETE CASCADE,
    text           text NOT NULL,
    follow_up_on   date,
    analyte_code   text REFERENCES analyte (code),
    concept        text,
    done_at        timestamptz,
    CHECK (num_nonnulls(analyte_code, concept) <= 1)
);

CREATE TABLE goal (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    type         text    NOT NULL CHECK (type IN ('water', 'sleep', 'exercise', 'custom')),
    target_value numeric NOT NULL CHECK (target_value > 0),
    unit         text    NOT NULL,
    period       text    NOT NULL CHECK (period IN ('day', 'week')),
    active       boolean NOT NULL DEFAULT true
);

CREATE TABLE reminder (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    kind         text    NOT NULL CHECK (kind IN ('water', 'sleep', 'exercise', 'custom')),
    cron         text    NOT NULL,
    message      text    NOT NULL,
    goal_id      uuid REFERENCES goal (id) ON DELETE SET NULL,
    enabled      boolean NOT NULL DEFAULT true,
    last_sent_at timestamptz
);

-- Timeline, goal progress and body map read confirmed events by time.
CREATE INDEX event_occurred_start_idx ON event (occurred_start);
CREATE INDEX event_confirmed_type_idx ON event (type, occurred_start) WHERE status = 'confirmed';
CREATE INDEX event_confirmed_region_idx ON event (body_region, occurred_start) WHERE status = 'confirmed' AND body_region IS NOT NULL;
CREATE INDEX event_pending_idx ON event (recorded_at) WHERE status = 'proposed';
CREATE INDEX event_source_idx ON event (source_id);

CREATE INDEX exam_collected_on_idx ON exam (collected_on);
CREATE INDEX exam_document_idx ON exam (document_id);
CREATE INDEX lab_result_exam_idx ON lab_result (exam_id);
CREATE INDEX lab_result_analyte_idx ON lab_result (analyte_code);

CREATE INDEX guidance_appointment_idx ON guidance (appointment_id);
CREATE INDEX guidance_open_follow_up_idx ON guidance (follow_up_on) WHERE done_at IS NULL AND follow_up_on IS NOT NULL;
